WITH base AS (SELECT *, DATE_TRUNC('month', sale_date) sale_date_period FROM store_sales WHERE sale_date BETWEEN '2023-04-01' AND '2025-06-24'), matched_keys AS (SELECT id, product_id FROM base EXCEPT SELECT id, product_id FROM store_sales WHERE units <> 30), verified AS (SELECT s.* FROM base s JOIN matched_keys k ON s.id = k.id AND s.product_id = k.product_id), joined AS (SELECT e.*, b.price FROM verified e JOIN products b ON e.product_id = b.id) SELECT DATE_TRUNC('QUARTER', sale_date) AS quarter_start, CASE WHEN units >= 36 THEN 'LARGE' ELSE 'SMALL' END AS units_tier, store_id, MAX(sale_date_period) AS last_seen, ROUND(AVG(revenue), 2) AS avg_revenue, GROUPING(DATE_TRUNC('QUARTER', sale_date)) AS grouping_level FROM joined GROUP BY GROUPING SETS ((DATE_TRUNC('QUARTER', sale_date), CASE WHEN units >= 36 THEN 'LARGE' ELSE 'SMALL' END, store_id), (DATE_TRUNC('QUARTER', sale_date), CASE WHEN units >= 36 THEN 'LARGE' ELSE 'SMALL' END), ()) ORDER BY quarter_start DESC NULLS LAST
